draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // person
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // cooking action
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 - 20, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 10);
  ctx.lineTo(W/2 - 50, H/2 + 10);
  ctx.stroke();
  ctx.save();
  ctx.translate(W/2 - 50, H/2);
  ctx.rotate(Math.sin(t));
  ctx.beginPath();
  ctx.moveTo(0, -10);
  ctx.lineTo(20, 0);
  ctx.stroke();
  ctx.restore();

  // family
  ctx.beginPath();
  ctx.arc(W/2 + 70, H/2 - 20, 15, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 70, H/2);
  ctx.lineTo(W/2 + 70, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 70, H/2 + 30);
  ctx.lineTo(W/2 + 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 70, H/2 + 30);
  ctx.lineTo(W/2 + 90, H/2 + 50);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2 - 20, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2);
  ctx.lineTo(W/2 + 100, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 20);
  ctx.lineTo(W/2 + 80, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 20);
  ctx.lineTo(W/2 + 120, H/2 + 40);
  ctx.stroke();

  ctx.restore();
}
